-- chair-step: inverse of read_lane_v2_b2_35_agent_mandate_note — un-enrolls agent.mandate_note from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'mandate_note' and is_active);
select iam.apply_rls('agent', 'mandate_note', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'mandate_note' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'mandate_note' and is_active));
